arguments.command:
cd /workspace && python3 - <<'EOF'
import os, shutil, stat
root = '/workspace/submission'
for base, dirs, files in os.walk(root, followlinks=False):
    for name in list(dirs):
        if name in ('__pycache__', '.pytest_cache', '.ruff_cache', '.git'):
            shutil.rmtree(os.path.join(base, name)); print('removed', os.path.join(base, name))
count = size = 0
for base, dirs, files in os.walk(root, followlinks=False):
    for name in dirs + files:
        st = os.lstat(os.path.join(base, name))
        assert stat.S_ISREG(st.st_mode) or stat.S_ISDIR(st.st_mode)
        count += 1
        if stat.S_ISREG(st.st_mode): size += st.st_size
print('final entries:', count, 'bytes:', size)
EOF
